//! Generated sources. A change to one is regenerated output of a change the
//! diff already shows at its source (siren #174: sqlc rewrote `(*Queries).Close`
//! and every `io.Closer.Close` in the repository became its consumer, 15 of the
//! block's entries).

/// Whether `text` carries a generated-code marker in its leading lines: Go's
/// `// Code generated ... DO NOT EDIT.`, the `@generated` tag, or a comment
/// naming a generator and ruling out edits (Python protobuf, TypeScript
/// codegen).
pub(super) fn generated(text: &str) -> bool {
    text.lines().take(10).any(|line| {
        let line = line.trim();
        let comment = ["//", "#", "/*", "*", "--"].iter().any(|c| line.starts_with(c));
        let lower = line.to_ascii_lowercase();
        (line.starts_with("// Code generated ") && line.ends_with("DO NOT EDIT."))
            || comment && line.contains("@generated")
            // Python protobuf, TypeScript codegen: a generator named and editing ruled out.
            || comment && lower.contains("generated") && lower.contains("do not edit")
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_generator_marker_in_the_header_marks_a_source_generated() {
        assert!(generated("// Code generated by sqlc. DO NOT EDIT.\n// versions:\npackage sqlcgen\n"));
        assert!(generated("# @generated by protoc\nimport x\n"));
        assert!(generated("/**\n * @generated\n */\nexport const a = 1;\n"));
        assert!(!generated("package app\n\n// Code generated elsewhere is not ours\nfunc A() {}\n"));
        assert!(!generated("package app\nfunc A() {}\n"));
        assert!(!generated("const tag = \"@generated\"\nexport const a = 1;\n"), "a string, not a comment");
        // Python protobuf and TypeScript generators word it their own way.
        assert!(generated("# -*- coding: utf-8 -*-\n# Generated by the protocol buffer compiler.  DO NOT EDIT!\n# source: a.proto\n"));
        assert!(generated("/* eslint-disable */\n// This file was automatically generated and should not be edited. Do not edit.\nexport type A = {};\n"));
        assert!(!generated("# Do not edit this list by hand.\nITEMS = []\n"), "no generator named");
    }
}
